import React, { useRef } from 'react';

export interface QrisUploaderProps {
  onSuccess: (qrisString: string) => void;
  onError?: (error: Error) => void;
  className?: string;
  buttonText?: string;
  loadingText?: string;
}

export function QrisUploader({ 
  onSuccess, 
  onError, 
  className = '', 
  buttonText = 'Upload Gambar QRIS', 
  loadingText = 'Memproses...' 
}: QrisUploaderProps) {
  const [isProcessing, setIsProcessing] = React.useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    
    try {
      // Dynamic import to avoid SSR issues with canvas/browser APIs
      const { readQrisFromImage } = await import('../image');
      const qrisString = await readQrisFromImage(file);
      
      if (!qrisString) {
        throw new Error('Kode QR tidak terdeteksi pada gambar');
      }
      
      onSuccess(qrisString);
    } catch (err: any) {
      if (onError) onError(err);
      else console.error(err);
    } finally {
      setIsProcessing(false);
      if (inputRef.current) {
        inputRef.current.value = ''; // Reset input
      }
    }
  };

  return (
    <div className={`indonesia-qris-uploader ${className}`}>
      <input
        type="file"
        accept="image/*"
        ref={inputRef}
        onChange={handleFileChange}
        style={{ display: 'none' }}
        id="qris-upload-input"
      />
      <label 
        htmlFor="qris-upload-input" 
        style={{
          cursor: isProcessing ? 'not-allowed' : 'pointer',
          display: 'inline-block',
          padding: '8px 16px',
          backgroundColor: '#0066cc',
          color: 'white',
          borderRadius: '4px',
          fontWeight: 500,
          opacity: isProcessing ? 0.7 : 1
        }}
      >
        {isProcessing ? loadingText : buttonText}
      </label>
    </div>
  );
}
